    source: "//@version=6\r\n// Copyright (c) 2018-present, Alex Orekhov (everget)\r\n// Moving Average 3.0 (3rd Generation) script may be freely distributed under the MIT license.\r\nindicator(\"Moving Average 3.0 (3rd Generation)\", shorttitle=\"NMA\", overlay=true)\r\n\r\nlength1 = input.int(14, minval = 1, title = \"1st Length\")\r\nlength2 = input.int(3, minval = 1, title = \"2nd Length\")\r\nmaInput = input.string(\"EMA\", options = [\"EMA\", \"SMA\", \"VWMA\", \"WMA\"], title = \"MA Type\")\r\nsrc = input.source(close, title = \"Source\")\r\n\r\ngetMA(src, length) =>\r\n    ma = 0.0\r\n\r\n    if maInput == \"EMA\"\r\n        ma := ta.ema(src, length)\r\n\r\n    if maInput == \"SMA\"\r\n        ma := ta.sma(src, length)\r\n\r\n    if maInput == \"VWMA\"\r\n        ma := ta.vwma(src, length)\r\n\r\n    if maInput == \"WMA\"\r\n        ma := ta.wma(src, length)\r\n    ma\r\n\r\ngetNMA(src, length1, length2) =>\r\n    lambda = length1 / length2\r\n\talpha = lambda * (length1 - 1) / (length1 - lambda)\r\n\t\r\n\tma1 = getMA(src, length1)\r\n\tma2 = getMA(ma1, length2)\r\n\r\n\tnma = (1 + alpha) * ma1 - alpha * ma2\r\n\r\nnma = getNMA(src, length1, length2)\r\n\r\nplot(nma, title=\"NMA\", linewidth=2, color=#6d1e7f)",
