    source: "//@version=6\r\n// Copyright (c) 2018-present, Alex Orekhov (everget)\r\n// Jurik Moving Average Surrogate script may be freely distributed under the MIT license.\r\nindicator('Jurik Moving Average Surrogate', shorttitle = 'JMA Surrogate', overlay = true, behind_chart = false)\r\n\r\nlength = input.int(7, minval = 1, title = 'Length')\r\nphase = input.int(100, minval = -100, maxval = 100, title = 'Phase')\r\npower = input.int(2, minval = 1, title = 'Power')\r\nsrc = input.source(close, title = 'Source')\r\n\r\nhighlightDirection = input.bool(\r\n     true,\r\n     title = 'Highlight Direction',\r\n     tooltip = 'Colors the JMA according to its direction:\\n• Green = rising\\n• Pink = falling'\r\n     )\r\n\r\napplyBarColors = input.bool(\r\n     true,\r\n     title = 'Apply Bar Colors',\r\n     tooltip = 'Colors price bars according to the JMA direction:\\n• Bullish color = rising JMA\\n• Bearish color = falling JMA'\r\n     )\r\n\r\napplyBgColors = input.bool(\r\n     false,\r\n     title = 'Apply Background Colors',\r\n     tooltip = 'Colors the chart background according to the JMA direction:\\n• Bullish color = rising JMA\\n• Bearish color = falling JMA'\r\n     )\r\n\r\nawaitBarConfirmation = input.bool(\r\n     true,\r\n     title = 'Await Bar Confirmation',\r\n     tooltip = 'Updates the JMA direction and triggers alerts only after the current bar closes.'\r\n     )\r\n\r\n//---\r\n\r\nphaseRatio = phase < -100 ? 0.5 : phase > 100 ? 2.5 : phase / 100 + 1.5\r\nbeta = 0.45 * (length - 1) / (0.45 * (length - 1) + 2)\r\nalpha = math.pow(beta, power)\r\n\r\njma = 0.0\r\ne0 = 0.0\r\ne0 := (1 - alpha) * src + alpha * nz(e0[1])\r\n\r\ne1 = 0.0\r\ne1 := (1 - beta) * (src - e0) + beta * nz(e1[1])\r\n\r\ne2 = 0.0\r\ne2 := math.pow(1 - alpha, 2) * (e0 + phaseRatio * e1 - nz(jma[1])) + math.pow(alpha, 2) * nz(e2[1])\r\n\r\njma := e2 + nz(jma[1])\r\n\r\n//---\r\n\r\nconst color bullishJMAColor = #09b71e\r\nconst color bearishJMAColor = #e91e63\r\nconst color defaultJMAColor = #6d1e7f\r\n\r\nconst color bullishColor = #4CAF50\r\nconst color bearishColor = #F44336\r\n\r\nconst color bullishBarColor = color.new(bullishColor, 50)\r\nconst color bearishBarColor = color.new(bearishColor, 50)\r\n\r\nconst color bullishBgColor = color.new(bullishColor, 88)\r\nconst color bearishBgColor = color.new(bearishColor, 88)\r\n\r\nisBullishSlope = jma > jma[1]\r\nawait = awaitBarConfirmation ? barstate.isconfirmed : true\r\n\r\nmaColor = highlightDirection\r\n     ? (isBullishSlope ? bullishJMAColor : bearishJMAColor)\r\n     : defaultJMAColor\r\n\r\nplot(jma, title = 'JMA', linewidth = 2, color = maColor)\r\n\r\njmaBarColor = isBullishSlope ? bullishBarColor : bearishBarColor\r\njmaBgColor = isBullishSlope ? bullishBgColor : bearishBgColor\r\n\r\nbarcolor(title = 'Bar Color', color = applyBarColors ? jmaBarColor : na)\r\nbgcolor(title = 'Background Color', color = applyBgColors ? jmaBgColor : na)\r\n\r\n//---\r\n\r\nbullishColorChangeAlert = maColor == bullishJMAColor and maColor[1] != bullishJMAColor and await\r\nbearishColorChangeAlert = maColor == bearishJMAColor and maColor[1] != bearishJMAColor and await\r\nanyColorChangeAlert = maColor != maColor[1] and await\r\n\r\nalertcondition(bullishColorChangeAlert, title = 'Bullish Color Change', message = 'JMA Surrogate - Bullish Color Change\\nSymbol: {{exchange}}:{{ticker}}\\nPrice: {{close}}')\r\nalertcondition(bearishColorChangeAlert, title = 'Bearish Color Change', message = 'JMA Surrogate - Bearish Color Change\\nSymbol: {{exchange}}:{{ticker}}\\nPrice: {{close}}')\r\nalertcondition(anyColorChangeAlert, title = 'Any Color Change', message = 'JMA Surrogate - Any Color Change\\nSymbol: {{exchange}}:{{ticker}}\\nPrice: {{close}}')",
