    source: "//@version=6\r\n// Copyright (c) 2019-present, Alex Orekhov (everget)\r\n// Ehlers Simple Decycler script may be freely distributed under the MIT license.\r\nindicator(\"Ehlers Simple Decycler\", shorttitle=\"Decycler\", overlay=true)\r\n\r\nhighpassLength = input.int(125, title = \"Highpass Period\")\r\nupperPercent = input.float(0.5, minval = 0, step = 0.1, title = \"Upper Band % Shift\")\r\nlowerPercent = input.float(0.5, minval = 0, step = 0.1, title = \"Lower Band % Shift\")\r\nsrc = input.source(close, title = \"Source\")\r\nhighlightMovements = input.bool(true, title = \"Highlight Decycler Movements ?\")\r\n\r\nPI = 2 * math.asin(1)\r\n\r\n// High-pass Filter\r\nalphaArg = 2 * PI / (highpassLength * math.sqrt(2))\r\n\r\nalpha = 0.0\r\nalpha := math.cos(alphaArg) != 0\r\n     ? (math.cos(alphaArg) + math.sin(alphaArg) - 1) / math.cos(alphaArg)\r\n     : nz(alpha[1])\r\n\r\nhp = 0.0\r\nhp := math.pow(1 - (alpha / 2), 2) * (src - 2 * nz(src[1]) + nz(src[2])) + 2 * (1 - alpha) * nz(hp[1]) - math.pow(1 - alpha, 2) * nz(hp[2])\r\n\r\ndecycler = src - hp\r\n\r\ndecyclerColor = highlightMovements ? (decycler >= decycler[1] ? color.green : color.red) : #741b47\r\nplot(decycler, title=\"Decycler\", linewidth=2, color=decyclerColor)\r\n\r\nupperBand = (1 + upperPercent / 100) * decycler\r\nlowerBand = (1 - lowerPercent / 100) * decycler\r\n\r\nbandColor = #138484\r\nupperBandPlot = plot(upperBand, title=\"Upper\", color=bandColor)\r\nlowerBandPlot = plot(lowerBand, title=\"Lower\", color=bandColor)\r\nfill(upperBandPlot, lowerBandPlot, title=\"Background\", color=color.new(#ffd966, 84))",
