    description: "everget · Moving Averages & Filters · ported from Pine v3/v4",
    sourceUrl: "https://www.tradingview.com/script/aaWzn9bK-Ehlers-MESA-Adaptive-Moving-Averages-MAMA-FAMA/",
    source: "//@version=6\r\n// Copyright (c) 2018-present, Alex Orekhov (everget)\r\n// Ehlers MESA Adaptive Moving Averages (MAMA & FAMA)script may be freely distributed under the terms of the GPL-3.0 license.\r\nindicator(\"Ehlers MESA Adaptive Moving Averages (MAMA & FAMA)\", shorttitle=\"MAMA & FAMA\", overlay=true)\r\n\r\nfastLimit = input.float(0.5, step = 0.01, title = \"Fast Limit\")\r\nslowLimit = input.float(0.05, step = 0.01, title = \"Slow Limit\")\r\napplyFilling = input.bool(true, title = \"Apply Ribbon Filling ?\")\r\nsrc = input.source(hl2, title = \"Source\")\r\n\r\nvar float PI = 2 * math.asin(1)\r\n\r\n// Truncated Hilbert transform\r\n_hilbertTransform(src) =>\r\n    out= 0.0962 * src + 0.5769 * nz(src[2]) - 0.5769 * nz(src[4]) - 0.0962 * nz(src[6])\r\n    out\r\n\r\n_computeComponent(src, mesaPeriodMult) =>\r\n    out = _hilbertTransform(src) * mesaPeriodMult\r\n    out\r\n\r\n_smoothComponent(src) =>\r\n    out = 0.2 * src + 0.8 * nz(src[1])\r\n    out\r\n\r\n_computeAlpha(src, fastLimit, slowLimit) =>\r\n    mesaPeriod = 0.0\r\n    mesaPeriodMult = 0.075 * nz(mesaPeriod[1]) + 0.54\r\n\r\n    smooth = (4 * src + 3 * nz(src[1]) + 2 * nz(src[2]) + nz(src[3])) / 10\r\n    detrender = _computeComponent(smooth, mesaPeriodMult)\r\n\r\n    // Compute InPhase and Quadrature components\r\n    I1 = nz(detrender[3])\r\n    Q1 = _computeComponent(detrender, mesaPeriodMult)\r\n\r\n    // Advance the phase of I1 and Q1 by 90 degrees\r\n    jI = _computeComponent(I1, mesaPeriodMult)\r\n    jQ = _computeComponent(Q1, mesaPeriodMult)\r\n\r\n    // Phasor addition for 3 bar averaging\r\n    I2 = I1 - jQ\r\n    Q2 = Q1 + jI\r\n\r\n    // Smooth the I and Q components before applying the discriminator\r\n    I2 := _smoothComponent(I2)\r\n    Q2 := _smoothComponent(Q2)\r\n\r\n    // Homodyne Discriminator\r\n    Re = I2 * nz(I2[1], I2) + Q2 * nz(Q2[1], Q2)\r\n    Im = I2 * nz(Q2[1], Q2) - Q2 * nz(I2[1], I2)\r\n\r\n    Re := _smoothComponent(Re)\r\n    Im := _smoothComponent(Im)\r\n\r\n    if Re != 0 and Im != 0\r\n        mesaPeriod := 2 * PI / math.atan(Im / Re)\r\n\r\n    mesaPeriod := math.min(mesaPeriod, 1.5 * nz(mesaPeriod[1], mesaPeriod))\r\n    mesaPeriod := math.max(mesaPeriod, 0.67 * nz(mesaPeriod[1], mesaPeriod))\r\n\tmesaPeriod := math.min(math.max(mesaPeriod, 6), 50)\r\n\tmesaPeriod := _smoothComponent(mesaPeriod)\r\n\r\n    phase = 0.0\r\n\r\n    if I1 != 0\r\n        phase := (180 / PI) * math.atan(Q1 / I1)\r\n\r\n    deltaPhase = nz(phase[1], phase) - phase\r\n    deltaPhase := math.max(deltaPhase, 1)\r\n\r\n    alpha = math.max(fastLimit / deltaPhase, slowLimit)\r\n\r\n    out = alpha\r\n    out\r\n\r\nalpha = _computeAlpha(src, fastLimit, slowLimit)\r\nalpha2 = alpha / 2\r\n\r\nmama = 0.0\r\nmama := alpha * src + (1 - alpha) * nz(mama[1])\r\n\r\nfama = 0.0\r\nfama := alpha2 * mama + (1 - alpha2) * nz(fama[1])\r\n\r\nmamaPlot = plot(mama, title=\"MAMA\", linewidth=2, color=#674ea7)\r\nfamaPlot = plot(fama, title=\"FAMA\", linewidth=2, color=#f6b26b)\r\n\r\nnoneColor = color.new(color.white, 100) \r\n\r\nfillColor = applyFilling ? (mama > fama ? #0ebb23 : #cc0000) : noneColor\r\nfill(mamaPlot, famaPlot, color=fillColor)\r\n\r\nlong = ta.crossover(mama, fama)\r\nshort = ta.crossunder(mama, fama)\r\n\r\nalertcondition(long, title=\"Alert: Long\", message=\"MAMA & FAMA Long!\")\r\nalertcondition(short, title=\"Alert: Short\", message=\"MAMA & FAMA Short!\")",
