    source: "//@version=6\r\n// Copyright (c) 2019-present, Alex Orekhov (everget)\r\n// Distance Weighted Moving Average script may be freely distributed under the MIT license.\r\nindicator(\"Distance Weighted Moving Average\", shorttitle=\"DWMA\", overlay=true)\r\n\r\nlength = input.int(14, title = \"Length\")\r\nhighlightMovements = input.bool(true, title = \"Highlight Movements ?\")\r\nsrc = input.source(close, title = \"Source\")\r\n\r\nsum = 0.0\r\nweightSum = 0.0\r\n\r\ncalcWeight(src, length, i) =>\r\n    distanceSum = 0.0\r\n    for j = 0 to length - 1\r\n        distanceSum := distanceSum + math.abs(nz(src[i]) - nz(src[j]))\r\n    1 / distanceSum\r\n\r\nfor i = 0 to length - 1\r\n    weight = calcWeight(src, length, i)\r\n    sum := sum + nz(src[i]) * weight\r\n    weightSum := weightSum + weight\r\n\r\ndwma = sum / weightSum\r\n    \r\ndwmaColor = highlightMovements ? (dwma > dwma[1] ? color.green : color.red) : #6d1e7f\r\nplot(dwma, title=\"DWMA\", linewidth=2, color=dwmaColor)",
