    source: "//@version=6\r\n// Copyright (c) 2019-present, Alex Orekhov (everget)\r\n// Inverse Distance Weighted Moving Average script may be freely distributed under the GPL-3.0 license.\r\nconst string MA_SHORT_TITLE = 'IDWMA'\r\nindicator('Inverse Distance Weighted Moving Average', shorttitle = MA_SHORT_TITLE, overlay = true, behind_chart = false)\r\n\r\nlength = input.int(14, minval = 1, title = 'Length')\r\nsrc = input.source(close, title = 'Source')\r\n\r\nvar highlightDirectionTooltip = 'Colors the ' + MA_SHORT_TITLE + ' according to its direction:\\n• Green = rising\\n• Pink = falling'\r\nhighlightDirection = input.bool(\r\n     true\r\n     , title = 'Highlight Direction'\r\n     , tooltip = highlightDirectionTooltip\r\n     )\r\n\r\nvar applyBarColorsTooltip = 'Colors price bars according to the ' + MA_SHORT_TITLE + ' direction:\\n• Bullish color = rising ' + MA_SHORT_TITLE + '\\n• Bearish color = falling ' + MA_SHORT_TITLE\r\napplyBarColors = input.bool(\r\n     true\r\n     , title = 'Apply Bar Colors'\r\n     , tooltip = applyBarColorsTooltip\r\n     )\r\n\r\nvar applyBgColorsTooltip = 'Colors the chart background according to the ' + MA_SHORT_TITLE + ' direction:\\n• Bullish color = rising ' + MA_SHORT_TITLE + '\\n• Bearish color = falling ' + MA_SHORT_TITLE\r\napplyBgColors = input.bool(\r\n     false\r\n     , title = 'Apply Background Colors'\r\n     , tooltip = applyBgColorsTooltip\r\n     )\r\n\r\n//---\r\n\r\n// |src[i] - src[j]| is symmetric, so walk each unordered pair once and credit the distance\r\n// to both taps - half the work of computing every tap's weight independently\r\nvar array<float> weights = array.new_float(length, 0.0)\r\nfor i = 0 to length - 1\r\n    array.set(weights, i, 0.0)\r\n// Guarded: at length == 1 the bounds would invert and Pine's auto-reversing for-loop\r\n// would index the array out of range\r\nif length > 1\r\n    for i = 0 to length - 2\r\n        for j = i + 1 to length - 1\r\n            d = math.abs(nz(src[i], src) - nz(src[j], src))\r\n            array.set(weights, i, array.get(weights, i) + d)\r\n            array.set(weights, j, array.get(weights, j) + d)\r\n\r\nsum = 0.0\r\nweightSum = 0.0\r\nfor i = 0 to length - 1\r\n    weight = array.get(weights, i)\r\n    sum += nz(src[i], src) * weight\r\n    weightSum += weight\r\n// A perfectly flat window makes every distance - and therefore every weight - zero\r\nma = weightSum != 0 ? sum / weightSum : src\r\n\r\n//---\r\n\r\nconst color bullishColor = #09b71e\r\nconst color bearishColor = #e91e63\r\n\r\nconst color bullishBarColor = color.new(bullishColor, 50)\r\nconst color bearishBarColor = color.new(bearishColor, 50)\r\n\r\nconst color bullishWickColor = bullishColor\r\nconst color bearishWickColor = bearishColor\r\n\r\nconst color bullishBgColor = color.new(bullishColor, 88)\r\nconst color bearishBgColor = color.new(bearishColor, 88)\r\n\r\nisBullishSlope = ma > ma[1]\r\n\r\nmaColor = highlightDirection\r\n     ? (isBullishSlope ? bullishColor : bearishColor)\r\n     : #512da8\r\n\r\nplot(ma, title = MA_SHORT_TITLE, linewidth = 2, color = maColor)\r\n\r\nmaBarColor = applyBarColors ? (isBullishSlope ? bullishBarColor : bearishBarColor) : na\r\nmaWickColor = applyBarColors ? (isBullishSlope ? bullishWickColor : bearishWickColor) : na\r\nmaBgColor = applyBgColors ? (isBullishSlope ? bullishBgColor : bearishBgColor) : na\r\n\r\nbarcolor(title = 'Bar Color', color = maBarColor)\r\nplotcandle(open, high, low, close, title = 'Bar Color', color = na, wickcolor = maWickColor, bordercolor = na, display = display.pane)\r\nbgcolor(title = 'Background Color', color = maBgColor)\r\n\r\n//---\r\n\r\nbullishColorChangeAlert = maColor[1] != bullishColor and maColor == bullishColor\r\nbearishColorChangeAlert = maColor[1] != bearishColor and maColor == bearishColor\r\nanyColorChangeAlert = maColor != maColor[1]\r\n\r\nalertcondition(bullishColorChangeAlert, title = 'Bullish Color Change', message = MA_SHORT_TITLE + ' - Bullish Color Change\\nSymbol: {{exchange}}:{{ticker}}\\nPrice: {{close}}')\r\nalertcondition(bearishColorChangeAlert, title = 'Bearish Color Change', message = MA_SHORT_TITLE + ' - Bearish Color Change\\nSymbol: {{exchange}}:{{ticker}}\\nPrice: {{close}}')\r\nalertcondition(anyColorChangeAlert, title = 'Any Color Change', message = MA_SHORT_TITLE + ' - Any Color Change\\nSymbol: {{exchange}}:{{ticker}}\\nPrice: {{close}}')",
