    description: "everget · Moving Averages & Filters · ported from Pine v3/v4",
    sourceUrl: "https://www.tradingview.com/script/O7gCMT1q-McNicholl-Moving-Average/",
    source: "//@version=6\r\n// Copyright (c) 1998-present, Dennis McNicholl\r\n// Copyright (c) 2019-present, Alex Orekhov (everget)\r\n// McNicholl Moving Average script may be freely distributed under the MIT license.\r\nindicator(\"McNicholl Moving Average\", shorttitle=\"MNMA\", overlay=true)\r\n\r\nlength = input.int(20, title = \"Length\")\r\nhighlightMovements = input.bool(true, title = \"Highlight Movements ?\")\r\nsrc = input.source(close, title = \"Source\")\r\n\r\nalpha = 2 / (length + 1)\r\n\r\nema1 = ta.ema(src, length)\r\nema2 = ta.ema(ema1, length)\r\n\r\nmnma = ((2 - alpha) * ema1 - ema2) / (1 - alpha)\r\n\r\nmnmaColor = highlightMovements ? (mnma > mnma[1] ? color.green : color.red) : #6d1e7f\r\nplot(mnma, title=\"MNMA\", linewidth=2, color=mnmaColor)",
