    source: "//@version=6\r\n// Copyright (c) 2018-present, Alex Orekhov (everget)\r\n// Ahrens Moving Average script may be freely distributed under the MIT license.\r\nindicator(\"Ahrens Moving Average\", shorttitle=\"AHMA\", overlay=true)\r\n\r\nlength = input.int(9, title = \"Length\")\r\nhighlightMovements = input.bool(true, title = \"Highlight Movements ?\")\r\nsrc = input.source(close, title = \"Source\")\r\n\r\nahma = 0.0\r\nahma := nz(ahma[1]) + (src - (nz(ahma[1]) + nz(ahma[length])) / 2) / length \r\n\r\nahmaColor = highlightMovements ? (ahma > ahma[1] ? color.green : color.red) : #6d1e7f\r\nplot(ahma, title=\"AHMA\", linewidth=2, color=ahmaColor)",
