    source: "//@version=6\r\n// Copyright (c) 2018-present, Alex Orekhov (everget)\r\n// Ehlers Leading Indicator script may be freely distributed under the MIT license.\r\nindicator(\"Ehlers Leading Indicator\", shorttitle=\"ELI\", overlay=true)\r\n\r\nalpha1 = input.float(0.25, step = 0.1, title = \"Alpha 1\")\r\nalpha2 = input.float(0.33, step = 0.1, title = \"Alpha 2\")\r\nsrc = input.source(hl2, title = \"Source\")\r\n\r\nlead = 0.0\r\nlead := 2 * src + (alpha1 - 2) * nz(src[1]) + (1 - alpha1) * nz(lead[1])\r\n\r\nleadingIndicator = 0.0\r\nleadingIndicator := alpha2 * lead + (1 - alpha2) * nz(leadingIndicator[1]) \r\n\r\nplot(leadingIndicator, title=\"ELI\", linewidth=2, color=#741b47)",
