    source: "//@version=6\r\n// Copyright (c) 2018-present, Alex Orekhov (everget)\r\n// Moving Median script may be freely distributed under the MIT license.\r\nindicator(\"Moving Median\", shorttitle=\"MM\", overlay=true)\r\n\r\nlength = input.int(14, title = \"Length\")\r\nhighlightMovements = input.bool(true, title = \"Highlight Movements ?\")\r\nsrc = input.source(close, title = \"Source\")\r\n\r\nmedian = ta.percentile_nearest_rank(src, length, 50)\r\n\r\nmedianColor = highlightMovements ? (median > median[1] ? color.green : color.red) : #6d1e7f\r\nplot(median, title=\"MM\", linewidth=2, color=medianColor)",
