    source: "//@version=6\r\n// Copyright (c) 2017-present, Alex Orekhov (everget)\r\n// Moving Average Channel script may be freely distributed under the terms of the GPL-3.0 license.\r\nindicator(\"Moving Average Channel\", shorttitle=\"MAC\", overlay=true)\r\n\r\nupperSrc = input.source(high, title = \"Upper Source\")\r\nupperLength = input.int(20, title = \"Upper Length\")\r\nupperOffset = input.int(0, title = \"Upper Offset\")\r\n\r\nupper = ta.sma(upperSrc, upperLength)\r\nupperPlot = plot(upper, title=\"Upper\", color=#3c78d8, offset=upperOffset)\r\n\r\nlowerSrc = input.source(low, title = \"Lower Source\")\r\nlowerLength = input.int(20, title = \"Lower Length\")\r\nlowerOffset = input.int(0, title = \"Lower Offset\")\r\n\r\nlower = ta.sma(lowerSrc, lowerLength)\r\nlowerPlot = plot(lower, title=\"Lower\", color=#f57c00, offset=lowerOffset)\r\n\r\nfill(upperPlot, lowerPlot, title=\"Background\", color=color.new(#ffd966, 90))\r\n\r\nbarColor = close > upper ? color.lime : close < lower ? color.red : color.gray\r\nbarcolor(barColor, title=\"Bar Color\")",
