    source: "//@version=6\r\n// Copyright (c) 2018-present, Alex Orekhov (everget)\r\n// Percentage Volume Oscillator script may be freely distributed under the MIT license.\r\nindicator(\"Percentage Volume Oscillator\", shorttitle=\"PVO\")\r\n\r\nfastLength = input.int(12, title = \"Fast Length\")\r\nslowLength = input.int(26, title = \"Slow Length\")\r\nsignalLength = input.int(9, title = \"Signal Length\")\r\nshowHistogram = input.bool(true, title = \"Show Histogram ?\")\r\nhighlightCrossovers = input.bool(true, title = \"Highlight PVO/Signal Crossovers ?\")\r\nhighlightZeroCrossovers = input.bool(false, title = \"Highlight Zero Line Crossovers ?\")\r\napplyFilling = input.bool(false, title = \"Apply Ribbon Filling ?\")\r\n\r\nsrc = volume\r\n\r\npvo = 100 * (ta.ema(src, fastLength) - ta.ema(src, slowLength)) / ta.ema(src, slowLength)\r\nsignal = ta.ema(pvo, signalLength)\r\n\r\nhist = pvo - signal\r\nhistColor = hist >= 0 ? (hist[1] < hist ? #26A69A : #B2DFDB) : (hist[1] < hist ? #FFCDD2 : #EF5350)\r\n\r\nplot(showHistogram ? hist : na, title=\"Histogram\", style=columns, color=histColor)\r\nhline(0, title=\"Zero Line\", linestyle=dotted)\r\n\r\ntrendColor = pvo > signal ? #0ebb23 : color.red\r\npvoColor = applyFilling ? trendColor : #0094ff\r\nsignalColor = applyFilling ? trendColor : #ff6a00\r\n\r\npvoPlot = plot(pvo, title=\"PVO\", color=pvoColor)\r\nsignalPlot = plot(signal, title=\"Signal\", color=signalColor)\r\n\r\ntransparent = color(color.white, 100)\r\n\r\nfillColor = applyFilling ? trendColor : transparent\r\nfill(pvoPlot, signalPlot, color=fillColor)\r\n\r\nzeroCrossBgColor = highlightZeroCrossovers ? (pvo > 0 ? color.green : color.red) : transparent\r\nbgcolor(zeroCrossBgColor)\r\n\r\nplotshape(highlightCrossovers and ta.crossover(pvo, signal) ? pvo : na, title=\"Crossover\", location=location.absolute, style=shape.circle, size=size.tiny, color=color.green)\r\nplotshape(highlightCrossovers and ta.crossunder(pvo, signal) ? pvo : na, title=\"Crossunder\", location=location.absolute, style=shape.circle, size=size.tiny, color=color.red)",
